def process_slash_command(command, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        # deterministic enough, matches existing prefix style without requiring ULID
        return f"{prefix}_01{secrets.token_hex(13).upper()}"

    def _record_event(event_type, *, status, prompt_id=None, raw_command=None, command_name=None,
                      arguments_json=None, filter_text=None, section_name=None,
                      restart_requested=False, reason=None, error_message=None):
        events = _load("prompt_events.json")
        if not isinstance(events, list):
            events = []
        ev = {
            "id": _new_id("pevt"),
            "event_type": event_type,
            "prompt_id": prompt_id,
            "raw_command": raw_command,
            "command_name": command_name,
            "arguments_json": arguments_json,
            "filter_text": filter_text,
            "section_name": section_name,
            "restart_requested": bool(restart_requested),
            "reason": reason,
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        # constraint: status='failed' implies error_message not null
        if ev["status"] == "failed" and not isinstance(ev.get("error_message"), str):
            ev["error_message"] = "Failed"
        # constraint: event_type='command_processed' implies raw_command is not null
        if ev["event_type"] == "command_processed" and not isinstance(ev.get("raw_command"), str):
            ev["raw_command"] = "" if raw_command is None else str(raw_command)
        events.append(ev)
        _save("prompt_events.json", events)
        return ev

    def _enforce_rate_limits_or_refuse():
        # Rate: 120 calls / rolling minute; Quota: 10k calls / UTC day (based on prompt_events)
        events = _load("prompt_events.json")
        if not isinstance(events, list):
            events = []
        cutoff = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0)
        calls_last_min = 0
        calls_today = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            dt = _parse_dt(e.get("created_at"))
            if not dt:
                continue
            if dt >= cutoff:
                calls_last_min += 1
            if dt >= day_start:
                calls_today += 1
        if calls_last_min >= 120:
            _record_event(
                "command_processed",
                status="failed",
                raw_command=command if isinstance(command, str) else None,
                command_name=None,
                arguments_json=None,
                error_message="Rate limited: more than 120 calls per rolling minute"
            )
            return _err("RATE_LIMIT", "Rate limited: too many requests", retry_after_seconds=60, limit_per_minute=120)
        if calls_today >= 10000:
            _record_event(
                "command_processed",
                status="failed",
                raw_command=command if isinstance(command, str) else None,
                command_name=None,
                arguments_json=None,
                error_message="Quota exceeded: more than 10000 calls per UTC day"
            )
            return _err("QUOTA_EXCEEDED", "Quota exceeded for today", limit_per_day=10000)
        return None

    # Validate input first
    if not isinstance(command, str):
        # record as failed command_processed (observability)
        _record_event(
            "command_processed",
            status="failed",
            raw_command=None,
            command_name=None,
            arguments_json=None,
            error_message="Validation error: command must be a string"
        )
        return _err("VALIDATION_ERROR", "command must be a string", field="command")

    # Rate/quota check (must be enforced against records)
    refusal = _enforce_rate_limits_or_refuse()
    if refusal:
        return refusal

    raw = command.strip()
    if not raw:
        _record_event(
            "command_processed",
            status="failed",
            raw_command=command,
            command_name=None,
            arguments_json=None,
            error_message="Validation error: command string is empty"
        )
        return _err("VALIDATION_ERROR", "Command string is empty", rule="command must be non-empty")

    # Parse formats:
    #   "/name rest..."
    #   ">>name rest..."
    #   "name rest..." (allowed; datastore example shows calling with "meeting_notes")
    m = re.match(r"^\s*(?:/|>>)?\s*([A-Za-z0-9][A-Za-z0-9_\-]*)\s*(.*)$", raw)
    if not m:
        _record_event(
            "command_processed",
            status="failed",
            raw_command=command,
            command_name=None,
            arguments_json=None,
            error_message="Validation error: malformed command"
        )
        return _err("VALIDATION_ERROR", "Malformed command string", rule="must match /name … or >>name … or name …")

    cmd_name = m.group(1)
    rest = m.group(2) if m.group(2) is not None else ""
    rest = rest.strip()

    # Parse arguments:
    # Support:
    #   key=value tokens (quoted values supported)
    #   everything else becomes {"input": "..."} if non-empty and no explicit key= tokens
    args = {}
    used_key_value = False
    if rest:
        # tokenize preserving quoted strings
        tokens = re.findall(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''', rest)
        flat = []
        for a, b, c in tokens:
            flat.append(a if a != "" else (b if b != "" else c))
        for tok in flat:
            if isinstance(tok, str) and "=" in tok:
                k, v = tok.split("=", 1)
                k = k.strip()
                v = v.strip()
                if k:
                    args[k] = v
                    used_key_value = True
            else:
                # non key=value token(s)
                pass
        if not used_key_value:
            args["input"] = rest

    # Resolve exactly one active prompt by command_name
    prompts = _load("prompts.json")
    if not isinstance(prompts, list):
        prompts = []
    matches = []
    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if p.get("command_name") == cmd_name:
            matches.append(p)
    if len(matches) != 1:
        err_msg = f"No active prompt found for command_name '{cmd_name}'" if len(matches) == 0 else f"Multiple active prompts found for command_name '{cmd_name}'"
        _record_event(
            "command_processed",
            status="failed",
            raw_command=command,
            command_name=cmd_name,
            arguments_json=args if args else {},
            error_message=err_msg
        )
        code = "NOT_FOUND" if len(matches) == 0 else "CONFLICT"
        return _err(code, err_msg, command_name=cmd_name)

    prompt = matches[0]
    prompt_id = prompt.get("id")

    # Load prompt arguments definition
    pargs = _load("prompt_arguments.json")
    if not isinstance(pargs, list):
        pargs = []
    defs = [a for a in pargs if isinstance(a, dict) and a.get("prompt_id") == prompt_id]
    # order by position
    def _pos(x):
        try:
            return int(x.get("position", 10**9))
        except Exception:
            return 10**9
    defs.sort(key=_pos)

    # Validate required args: only enforce those defined for this prompt
    missing = []
    bound = dict(args) if isinstance(args, dict) else {}
    for d in defs:
        if d.get("required") is True:
            nm = d.get("name")
            if isinstance(nm, str) and nm.strip():
                if nm not in bound or bound.get(nm) in (None, ""):
                    missing.append(nm)
    if missing:
        msg = "Required arguments missing: " + ", ".join(missing)
        _record_event(
            "command_processed",
            status="failed",
            prompt_id=prompt_id,
            raw_command=command,
            command_name=cmd_name,
            arguments_json=bound,
            error_message=msg
        )
        return _err("VALIDATION_ERROR", msg, missing_arguments=missing, rule="required arguments cannot be satisfied")

    # Render messages
    system_message = prompt.get("system_message")
    user_tmpl = prompt.get("user_message_template")

    if user_tmpl is None or not isinstance(user_tmpl, str) or user_tmpl == "":
        # schema says user_message_template non-null/non-empty; but be defensive
        msg = "Prompt is misconfigured: user_message_template is empty"
        _record_event(
            "command_processed",
            status="failed",
            prompt_id=prompt_id,
            raw_command=command,
            command_name=cmd_name,
            arguments_json=bound,
            error_message=msg
        )
        return _err("CONFLICT", msg, prompt_id=prompt_id)

    # Safe-ish templating: support {name} placeholders; leave unknown placeholders intact
    class _SafeDict(dict):
        def __missing__(self, key):
            return "{" + key + "}"
    try:
        rendered_user = user_tmpl.format_map(_SafeDict(bound))
    except Exception:
        # if template uses invalid format syntax, fail as misconfiguration
        msg = "Prompt template formatting error"
        _record_event(
            "command_processed",
            status="failed",
            prompt_id=prompt_id,
            raw_command=command,
            command_name=cmd_name,
            arguments_json=bound,
            error_message=msg
        )
        return _err("CONFLICT", msg, prompt_id=prompt_id, rule="user_message_template must be valid format string")

    rendered = {
        "prompt": {
            "id": prompt.get("id"),
            "command_name": prompt.get("command_name"),
            "name": prompt.get("name"),
            "category": prompt.get("category"),
            "description": prompt.get("description"),
            "is_chain": prompt.get("is_chain"),
            "status": prompt.get("status"),
            "version": prompt.get("version"),
            "updated_at": prompt.get("updated_at"),
        },
        "parsed": {
            "command_name": cmd_name,
            "arguments": bound,
            "freeform_input": bound.get("input") if isinstance(bound, dict) else None,
        },
        "messages": [
            *([{"role": "system", "content": system_message}] if isinstance(system_message, str) and system_message != "" else []),
            {"role": "user", "content": rendered_user},
        ],
    }

    # Record success event (observability)
    _record_event(
        "command_processed",
        status="applied",
        prompt_id=prompt_id,
        raw_command=command,
        command_name=cmd_name,
        arguments_json=bound,
        error_message=None
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "result": rendered,
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": now,
        }
    }

def update_prompt(id, name, category, description, userMessageTemplate, arguments, systemMessage=None, isChain=None, chainSteps=None, restartServer=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _check_limits():
        events = _load("prompt_events.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for e in events:
            ca = e.get("created_at")
            if isinstance(ca, str) and ca >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        day = datetime.datetime.utcnow().strftime("%Y-%m-%d")
        daily = 0
        for e in events:
            ca = e.get("created_at")
            if isinstance(ca, str) and ca[:10] == day:
                daily += 1
        if daily >= 2000:  # tighter for writes
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded")
        return None

    lim = _check_limits()
    if lim:
        events = _load("prompt_events.json")
        events.append({
            "id": "pe_" + uuid.uuid4().hex,
            "event_type": "prompt_updated",
            "prompt_id": id if isinstance(id, str) else None,
            "raw_command": None,
            "command_name": None,
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": bool(restartServer) if isinstance(restartServer, bool) else False,
            "reason": None,
            "status": "failed",
            "error_message": lim["error"]["message"],
            "created_at": now,
            "updated_at": now
        })
        _save("prompt_events.json", events)
        return lim

    # Validate required types
    if not isinstance(id, str) or id.strip() == "":
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(name, str) or name.strip() == "":
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if not isinstance(category, str) or category.strip() == "":
        return _err("VALIDATION_ERROR", "category must be a non-empty string")
    if not isinstance(description, str) or description.strip() == "":
        return _err("VALIDATION_ERROR", "description must be a non-empty string")
    if systemMessage is not None and not isinstance(systemMessage, str):
        return _err("VALIDATION_ERROR", "systemMessage must be a string or null")
    if not isinstance(userMessageTemplate, str) or userMessageTemplate.strip() == "":
        return _err("VALIDATION_ERROR", "userMessageTemplate must be a non-empty string")
    if not isinstance(arguments, list):
        return _err("VALIDATION_ERROR", "arguments must be an array")
    if isChain is not None and not isinstance(isChain, bool):
        return _err("VALIDATION_ERROR", "isChain must be a boolean when provided")
    if chainSteps is not None and not isinstance(chainSteps, list):
        return _err("VALIDATION_ERROR", "chainSteps must be an array when provided")
    if restartServer is not None and not isinstance(restartServer, bool):
        return _err("VALIDATION_ERROR", "restartServer must be a boolean when provided")

    # Load prompt
    prompts = _load("prompts.json")
    pidx = None
    for i, p in enumerate(prompts):
        if p.get("id") == id:
            pidx = i
            break
    if pidx is None:
        events = _load("prompt_events.json")
        events.append({
            "id": "pe_" + uuid.uuid4().hex,
            "event_type": "prompt_updated",
            "prompt_id": id,
            "raw_command": None,
            "command_name": None,
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": bool(restartServer) if isinstance(restartServer, bool) else False,
            "reason": None,
            "status": "failed",
            "error_message": "Prompt not found",
            "created_at": now,
            "updated_at": now
        })
        _save("prompt_events.json", events)
        return _err("NOT_FOUND", "Prompt not found", id=id)

    prompt = prompts[pidx]

    # Disallow updates to deleted prompt
    if prompt.get("status") == "deleted":
        events = _load("prompt_events.json")
        events.append({
            "id": "pe_" + uuid.uuid4().hex,
            "event_type": "prompt_updated",
            "prompt_id": id,
            "raw_command": None,
            "command_name": prompt.get("command_name"),
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": bool(restartServer) if isinstance(restartServer, bool) else False,
            "reason": None,
            "status": "failed",
            "error_message": "Cannot update a deleted prompt",
            "created_at": now,
            "updated_at": now
        })
        _save("prompt_events.json", events)
        return _err("CONFLICT", "Cannot update a deleted prompt")

    # Enforce unique(command_name) among non-deleted prompts.
    # command_name is not part of tool surface; keep existing. (If schema had change, we'd reject collisions.)
    cmd_name = prompt.get("command_name")
    if not isinstance(cmd_name, str) or cmd_name.strip() == "":
        # If legacy row missing command_name, derive from id deterministically
        cmd_name = re.sub(r'[^A-Za-z0-9_\-]+', '_', id).strip("_") or ("prompt_" + uuid.uuid4().hex[:8])
    for other in prompts:
        if other.get("id") != id and other.get("status") != "deleted" and other.get("command_name") == cmd_name:
            return _err("CONFLICT", "command_name collision among non-deleted prompts", command_name=cmd_name)

    # Validate arguments payload & construct rows
    seen_arg_names = set()
    arg_rows_new = []
    pos = 1
    for a in arguments:
        if not isinstance(a, dict):
            return _err("VALIDATION_ERROR", "Each argument must be an object")
        if "name" not in a or "required" not in a:
            return _err("VALIDATION_ERROR", "Each argument must include name and required")
        an = a.get("name")
        ar = a.get("required")
        ad = a.get("description", None)
        if not isinstance(an, str) or an.strip() == "":
            return _err("VALIDATION_ERROR", "arguments[].name must be a non-empty string")
        if an in seen_arg_names:
            return _err("CONFLICT", "Duplicate argument name for prompt", name=an)
        seen_arg_names.add(an)
        if not isinstance(ar, bool):
            return _err("VALIDATION_ERROR", "arguments[].required must be boolean")
        if ad is not None and not isinstance(ad, str):
            return _err("VALIDATION_ERROR", "arguments[].description must be a string or null")
        arg_rows_new.append({
            "id": "parg_" + uuid.uuid4().hex,
            "prompt_id": id,
            "name": an,
            "description": ad,
            "required": ar,
            "position": pos,
            "created_at": now,
            "updated_at": now
        })
        pos += 1

    # Chain validation & replacement
    is_chain_val = bool(prompt.get("is_chain")) if isChain is None else isChain
    steps_payload = chainSteps if chainSteps is not None else ([] if is_chain_val else None)
    if is_chain_val and steps_payload is None:
        steps_payload = []
    if (not is_chain_val) and steps_payload is not None and len(steps_payload) > 0:
        return _err("VALIDATION_ERROR", "chainSteps must be omitted/empty when isChain is false")

    prompt_chain_steps = _load("prompt_chain_steps.json")

    # Validate step references if is chain
    steps_rows_new = []
    if is_chain_val:
        if steps_payload is None:
            steps_payload = []
        if not isinstance(steps_payload, list):
            return _err("VALIDATION_ERROR", "chainSteps must be an array")
        seen_step_names = set()
        for idx, st in enumerate(steps_payload, start=1):
            if not isinstance(st, dict):
                return _err("VALIDATION_ERROR", "Each chain step must be an object")
            if "promptId" not in st or "stepName" not in st:
                return _err("VALIDATION_ERROR", "Each chain step must include promptId and stepName")
            pid = st.get("promptId")
            sn = st.get("stepName")
            if not isinstance(pid, str) or pid.strip() == "":
                return _err("VALIDATION_ERROR", "chainSteps[].promptId must be a non-empty string")
            if not isinstance(sn, str) or sn.strip() == "":
                return _err("VALIDATION_ERROR", "chainSteps[].stepName must be a non-empty string")
            if sn in seen_step_names:
                return _err("CONFLICT", "Duplicate chain step name for chain prompt", stepName=sn)
            seen_step_names.add(sn)
            if pid == id:
                return _err("VALIDATION_ERROR", "chain_prompt_id must not equal prompt_id (self-reference)")
            im = st.get("inputMapping", None)
            om = st.get("outputMapping", None)
            if im is not None:
                if not isinstance(im, dict) or any((not isinstance(k, str) or not isinstance(v, str)) for k, v in im.items()):
                    return _err("VALIDATION_ERROR", "chainSteps[].inputMapping must be an object of string->string")
            if om is not None:
                if not isinstance(om, dict) or any((not isinstance(k, str) or not isinstance(v, str)) for k, v in om.items()):
                    return _err("VALIDATION_ERROR", "chainSteps[].outputMapping must be an object of string->string")

            # referenced prompt must exist and not be deleted
            ref = None
            for pp in prompts:
                if pp.get("id") == pid:
                    ref = pp
                    break
            if not ref or ref.get("status") not in ("active", "archived", "draft"):
                return _err("VALIDATION_ERROR", "chainSteps[].promptId must reference a non-deleted prompt", promptId=pid)

            steps_rows_new.append({
                "id": "pcs_" + uuid.uuid4().hex,
                "chain_prompt_id": id,
                "step_index": idx,
                "step_name": sn,
                "prompt_id": pid,
                "input_mapping": im,
                "output_mapping": om,
                "created_at": now,
                "updated_at": now
            })

        # enforce no cycles across prompt_chain_steps graph after applying changes
        # Build adjacency with prospective replacement for this chain prompt
        adjacency = {}
        for row in prompt_chain_steps:
            cp = row.get("chain_prompt_id")
            adjacency.setdefault(cp, set()).add(row.get("prompt_id"))
        # replace outgoing edges for this prompt
        adjacency[id] = set([r.get("prompt_id") for r in steps_rows_new])

        def _has_cycle(start):
            visiting = set()
            visited = set()
            def dfs(n):
                if n in visiting:
                    return True
                if n in visited:
                    return False
                visiting.add(n)
                for nxt in adjacency.get(n, set()):
                    if dfs(nxt):
                        return True
                visiting.remove(n)
                visited.add(n)
                return False
            return dfs(start)

        if _has_cycle(id):
            return _err("CONFLICT", "Chain steps would introduce a cycle")

    # Apply mutations atomically (best-effort in JSON files): compute new datasets then save
    prompt_arguments = _load("prompt_arguments.json")
    prompt_sections = _load("prompt_sections.json")

    # Update prompt fields
    changed = False
    def _set(field, newv):
        nonlocal changed
        if prompt.get(field) != newv:
            prompt[field] = newv
            changed = True

    _set("name", name)
    _set("category", category)
    _set("description", description)
    _set("system_message", systemMessage)
    _set("user_message_template", userMessageTemplate)
    _set("is_chain", is_chain_val)

    # Update updated_at/version if anything structural changes
    # Arguments always replaced; chain steps replaced/deleted depending on is_chain_val.
    # Treat as content/structure change even if equal sizes; real backend increments on update.
    changed = True

    # increment version monotonic >=1
    try:
        v = int(prompt.get("version") or 0)
    except Exception:
        v = 0
    prompt["version"] = max(1, v + 1)
    prompt["updated_at"] = now
    if not prompt.get("created_at"):
        prompt["created_at"] = now
    # ensure status valid
    if prompt.get("status") not in ("draft", "active", "archived", "deleted"):
        prompt["status"] = "draft"

    prompts[pidx] = prompt

    # Replace arguments
    prompt_arguments = [r for r in prompt_arguments if r.get("prompt_id") != id]
    prompt_arguments.extend(arg_rows_new)

    # Replace chain steps or delete if not chain
    if is_chain_val:
        prompt_chain_steps = [r for r in prompt_chain_steps if r.get("chain_prompt_id") != id]
        prompt_chain_steps.extend(steps_rows_new)
    else:
        prompt_chain_steps = [r for r in prompt_chain_steps if r.get("chain_prompt_id") != id]

    # Enforce: is_chain=false implies no rows exist for chain_prompt_id
    if not is_chain_val:
        if any(r.get("chain_prompt_id") == id for r in prompt_chain_steps):
            return _err("CONFLICT", "Non-chain prompt cannot have chain steps")

    # Persist
    _save("prompts.json", prompts)
    _save("prompt_arguments.json", prompt_arguments)
    _save("prompt_chain_steps.json", prompt_chain_steps)

    # Record events
    events = _load("prompt_events.json")
    ev_id = "pe_" + uuid.uuid4().hex
    events.append({
        "id": ev_id,
        "event_type": "prompt_updated",
        "prompt_id": id,
        "raw_command": None,
        "command_name": prompt.get("command_name"),
        "arguments_json": None,
        "filter_text": None,
        "section_name": None,
        "restart_requested": bool(restartServer) if isinstance(restartServer, bool) else False,
        "reason": None,
        "status": "recorded" if (restartServer is True) else "applied",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    if restartServer is True:
        events.append({
            "id": "pe_" + uuid.uuid4().hex,
            "event_type": "server_restart_requested",
            "prompt_id": id,
            "raw_command": None,
            "command_name": prompt.get("command_name"),
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": True,
            "reason": None,
            "status": "recorded",
            "error_message": None,
            "created_at": now,
            "updated_at": now
        })
    _save("prompt_events.json", events)

    # Return updated definition
    # Fetch arguments and steps from persisted lists
    args_out = [r for r in prompt_arguments if r.get("prompt_id") == id]
    args_out.sort(key=lambda r: (int(r.get("position") or 10**9), str(r.get("name") or "")))
    steps_out = [r for r in prompt_chain_steps if r.get("chain_prompt_id") == id]
    steps_out.sort(key=lambda r: int(r.get("step_index") or 10**9))

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "prompt": {
            "id": prompt.get("id"),
            "command_name": prompt.get("command_name"),
            "name": prompt.get("name"),
            "category": prompt.get("category"),
            "description": prompt.get("description"),
            "systemMessage": prompt.get("system_message"),
            "userMessageTemplate": prompt.get("user_message_template"),
            "isChain": bool(prompt.get("is_chain")),
            "status": prompt.get("status"),
            "version": prompt.get("version"),
            "created_at": prompt.get("created_at"),
            "updated_at": prompt.get("updated_at"),
            "arguments": [{
                "name": a.get("name"),
                "description": a.get("description"),
                "required": a.get("required")
            } for a in args_out],
            "chainSteps": (None if not bool(prompt.get("is_chain")) else [{
                "promptId": s.get("prompt_id"),
                "stepName": s.get("step_name"),
                "inputMapping": s.get("input_mapping"),
                "outputMapping": s.get("output_mapping")
            } for s in steps_out])
        },
        "event": {
            "event_type": "prompt_updated",
            "status": "recorded" if (restartServer is True) else "applied",
            "latency_ms": latency_ms,
            "created_at": now
        }
    }

def create_prompt(commandName, name, category, description, userMessageTemplate, arguments, systemMessage=None, isChain=None, chainSteps=None, status=None, restartServer=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validate required
    def _nonempty_str(v): return isinstance(v, str) and v.strip() != ""

    if not _nonempty_str(commandName):
        return _err("VALIDATION_ERROR", "commandName must be a non-empty string")
    if not _nonempty_str(name):
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if not _nonempty_str(category):
        return _err("VALIDATION_ERROR", "category must be a non-empty string")
    if not _nonempty_str(description):
        return _err("VALIDATION_ERROR", "description must be a non-empty string")
    if not _nonempty_str(userMessageTemplate):
        return _err("VALIDATION_ERROR", "userMessageTemplate must be a non-empty string")
    if not isinstance(arguments, list):
        return _err("VALIDATION_ERROR", "arguments must be an array")
    if systemMessage is not None and not isinstance(systemMessage, str):
        return _err("VALIDATION_ERROR", "systemMessage must be a string")
    if isChain is not None and not isinstance(isChain, bool):
        return _err("VALIDATION_ERROR", "isChain must be a boolean")
    if chainSteps is not None and not isinstance(chainSteps, list):
        return _err("VALIDATION_ERROR", "chainSteps must be an array")
    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "active", "archived"):
            return _err("VALIDATION_ERROR", "status must be one of: draft, active, archived")
    if restartServer is not None and not isinstance(restartServer, bool):
        return _err("VALIDATION_ERROR", "restartServer must be a boolean")

    # Defaults
    is_chain = bool(isChain) if isChain is not None else False
    chain_steps_in = chainSteps if chainSteps is not None else []
    initial_status = status if status is not None else "draft"

    if not is_chain and chain_steps_in:
        return _err("VALIDATION_ERROR", "chainSteps must be empty when isChain is false")

    # Validate arguments list
    seen_arg_names = set()
    positions = []
    for i, a in enumerate(arguments):
        if not isinstance(a, dict):
            return _err("VALIDATION_ERROR", f"arguments[{i}] must be an object")
        if not _nonempty_str(a.get("name")):
            return _err("VALIDATION_ERROR", f"arguments[{i}].name must be a non-empty string")
        if a["name"] in seen_arg_names:
            return _err("VALIDATION_ERROR", f"Duplicate argument name: {a['name']}")
        seen_arg_names.add(a["name"])
        if "description" in a and a["description"] is not None and not isinstance(a["description"], str):
            return _err("VALIDATION_ERROR", f"arguments[{i}].description must be a string")
        if not isinstance(a.get("required"), bool):
            return _err("VALIDATION_ERROR", f"arguments[{i}].required must be a boolean")
        pos = a.get("position", None)
        if pos is not None and not isinstance(pos, int):
            return _err("VALIDATION_ERROR", f"arguments[{i}].position must be an integer")
        positions.append(pos)

    # ---- Load datastore
    prompts = _load("prompts.json")
    prompt_args = _load("prompt_arguments.json")
    chain_steps = _load("prompt_chain_steps.json")
    events = _load("prompt_events.json")

    # Enforce unique(command_name) where status != 'deleted'
    for p in prompts:
        if p.get("status") != "deleted" and p.get("command_name") == commandName:
            return _err("CONFLICT", "commandName collides with an existing non-deleted prompt")

    # Validate chain steps and references (if chain)
    def _prompt_by_id(pid):
        return next((r for r in prompts if r.get("id") == pid), None)

    # Assign step indexes as 1-based (schema) from possible 0-based input
    normalized_steps = []
    if is_chain:
        seen_step_names = set()
        used_indexes = set()
        # Determine ordering: if stepIndex provided, sort by it; else preserve input order with sequential.
        # Treat input stepIndex as 0-based; store as 1-based.
        temp = []
        for i, s in enumerate(chain_steps_in):
            if not isinstance(s, dict):
                return _err("VALIDATION_ERROR", f"chainSteps[{i}] must be an object")
            if not _nonempty_str(s.get("promptId")):
                return _err("VALIDATION_ERROR", f"chainSteps[{i}].promptId must be a non-empty string")
            if not _nonempty_str(s.get("stepName")):
                return _err("VALIDATION_ERROR", f"chainSteps[{i}].stepName must be a non-empty string")
            if s["stepName"] in seen_step_names:
                return _err("VALIDATION_ERROR", f"Duplicate stepName: {s['stepName']}")
            seen_step_names.add(s["stepName"])
            si = s.get("stepIndex", None)
            if si is not None and not isinstance(si, int):
                return _err("VALIDATION_ERROR", f"chainSteps[{i}].stepIndex must be an integer")
            if "inputMapping" in s and s["inputMapping"] is not None:
                if not isinstance(s["inputMapping"], dict) or any(not isinstance(v, str) for v in s["inputMapping"].values()):
                    return _err("VALIDATION_ERROR", f"chainSteps[{i}].inputMapping must be an object with string values")
            if "outputMapping" in s and s["outputMapping"] is not None:
                if not isinstance(s["outputMapping"], dict) or any(not isinstance(v, str) for v in s["outputMapping"].values()):
                    return _err("VALIDATION_ERROR", f"chainSteps[{i}].outputMapping must be an object with string values")
            # referenced prompt must exist and not be deleted
            rp = _prompt_by_id(s["promptId"])
            if rp is None or rp.get("status") == "deleted":
                return _err("VALIDATION_ERROR", f"chainSteps[{i}].promptId must reference an existing non-deleted prompt")
            temp.append((si, i, s))

        # Sort: explicit stepIndex first (ascending); None keep relative after those without? We'll stable-sort by (has_index, index_or_large, original_pos)
        def _key(tup):
            si, orig_i, _ = tup
            return (0 if si is not None else 1, si if si is not None else orig_i, orig_i)
        temp.sort(key=_key)

        # Assign indexes: if any explicit indexes used, respect them but still enforce uniqueness and >=1 after conversion.
        next_auto = 0
        for si, orig_i, s in temp:
            if si is None:
                while next_auto in used_indexes:
                    next_auto += 1
                si0 = next_auto
                next_auto += 1
            else:
                si0 = si
            # input says minimum 0; schema requires >=1 so store si0+1
            if si0 < 0:
                return _err("VALIDATION_ERROR", f"chainSteps[{orig_i}].stepIndex must be >= 0")
            if si0 in used_indexes:
                return _err("VALIDATION_ERROR", "Duplicate stepIndex values are not allowed")
            used_indexes.add(si0)
            normalized_steps.append({
                "step_index": si0 + 1,
                "step_name": s["stepName"].strip(),
                "prompt_id": s["promptId"].strip(),
                "input_mapping": s.get("inputMapping"),
                "output_mapping": s.get("outputMapping"),
            })

        # No cycles across prompt_chain_steps graph: with new chain prompt node, cycles can only occur if any referenced prompt (directly/indirectly) references back to this new id.
        # New prompt id not yet assigned, so compute after id creation by checking reachability from referenced prompts to new prompt id (once known).
        # We'll do that after we create the prompt id, but prior to saving.

    # ---- Create prompt row
    pid = "pr_" + uuid.uuid4().hex
    prompt_row = {
        "id": pid,
        "command_name": commandName.strip(),
        "name": name.strip(),
        "category": category.strip(),
        "description": description.strip(),
        "system_message": systemMessage if systemMessage is not None else None,
        "user_message_template": userMessageTemplate,
        "is_chain": bool(is_chain),
        "status": initial_status,
        "version": 1,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Record mutation event (prompt_updated fits create too; schema lacks prompt_created)
    ev_id = "pe_" + uuid.uuid4().hex
    event_row = {
        "id": ev_id,
        "event_type": "prompt_updated",
        "prompt_id": pid,
        "raw_command": None,
        "command_name": prompt_row["command_name"],
        "arguments_json": None,
        "filter_text": None,
        "section_name": None,
        "restart_requested": bool(restartServer) if restartServer is not None else False,
        "reason": None,
        "status": "recorded",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Also record server_restart_requested if requested
    restart_event_id = None
    if bool(restartServer):
        restart_event_id = "pe_" + uuid.uuid4().hex
        restart_row = {
            "id": restart_event_id,
            "event_type": "server_restart_requested",
            "prompt_id": pid,
            "raw_command": None,
            "command_name": prompt_row["command_name"],
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": True,
            "reason": None,
            "status": "recorded",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        events.append(restart_row)

    # Cycle check now that pid is known (only for chains)
    if is_chain:
        # Build adjacency from existing chain steps: chain_prompt_id -> prompt_id
        adj = {}
        for cs in chain_steps:
            a = cs.get("chain_prompt_id")
            b = cs.get("prompt_id")
            if isinstance(a, str) and isinstance(b, str):
                adj.setdefault(a, set()).add(b)
        # Add prospective edges pid -> prompt_id for new chain
        adj.setdefault(pid, set())
        for ns in normalized_steps:
            adj[pid].add(ns["prompt_id"])

        # detect cycle involving pid: if pid reachable from any of its children, then cycle
        def _reachable(start, target):
            stack = [start]
            seen = set()
            while stack:
                x = stack.pop()
                if x == target:
                    return True
                if x in seen:
                    continue
                seen.add(x)
                for y in adj.get(x, ()):
                    if y not in seen:
                        stack.append(y)
            return False

        for child in adj.get(pid, set()):
            if _reachable(child, pid):
                return _err("VALIDATION_ERROR", "chainSteps introduces a cycle in the chain graph")

    # ---- Persist prompt and child rows
    prompts.append(prompt_row)

    # Replace all prompt_arguments for prompt (create => just insert)
    # Determine positions: use explicit if given else sequential starting at 1 in provided order.
    used_pos = set()
    next_pos = 1
    arg_rows_new = []
    for i, a in enumerate(arguments):
        pos = a.get("position", None)
        if pos is None:
            while next_pos in used_pos:
                next_pos += 1
            pos = next_pos
            next_pos += 1
        if not isinstance(pos, int) or pos < 1:
            return _err("VALIDATION_ERROR", f"arguments[{i}].position must be >= 1")
        if pos in used_pos:
            return _err("VALIDATION_ERROR", "Duplicate argument positions are not allowed")
        used_pos.add(pos)
        arg_rows_new.append({
            "id": "pa_" + uuid.uuid4().hex,
            "prompt_id": pid,
            "name": a["name"].strip(),
            "description": a.get("description"),
            "required": bool(a["required"]),
            "position": pos,
            "created_at": now,
            "updated_at": now,
        })

    prompt_args.extend(arg_rows_new)

    # Chain steps
    chain_rows_new = []
    if is_chain:
        for ns in normalized_steps:
            if ns["prompt_id"] == pid:
                return _err("VALIDATION_ERROR", "chain_prompt_id must not equal prompt_id (self-reference)")
            chain_rows_new.append({
                "id": "pcs_" + uuid.uuid4().hex,
                "chain_prompt_id": pid,
                "step_index": ns["step_index"],
                "step_name": ns["step_name"],
                "prompt_id": ns["prompt_id"],
                "input_mapping": ns.get("input_mapping"),
                "output_mapping": ns.get("output_mapping"),
                "created_at": now,
                "updated_at": now,
            })
        chain_steps.extend(chain_rows_new)

    # Mark events applied immediately in this offline implementation
    event_row["status"] = "applied"
    event_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    events.append(event_row)
    if bool(restartServer):
        for r in events:
            if r.get("id") == restart_event_id:
                r["status"] = "applied"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break

    _save("prompts.json", prompts)
    _save("prompt_arguments.json", prompt_args)
    _save("prompt_chain_steps.json", chain_steps)
    _save("prompt_events.json", events)

    return {
        "prompt": {
            "id": prompt_row["id"],
            "commandName": prompt_row["command_name"],
            "name": prompt_row["name"],
            "category": prompt_row["category"],
            "description": prompt_row["description"],
            "systemMessage": prompt_row["system_message"],
            "userMessageTemplate": prompt_row["user_message_template"],
            "isChain": bool(prompt_row["is_chain"]),
            "status": prompt_row["status"],
            "version": prompt_row["version"],
            "deletedAt": prompt_row["deleted_at"],
            "createdAt": prompt_row["created_at"],
            "updatedAt": prompt_row["updated_at"],
            "arguments": [
                {
                    "id": a["id"],
                    "name": a["name"],
                    "description": a["description"],
                    "required": bool(a["required"]),
                    "position": a["position"],
                    "createdAt": a["created_at"],
                    "updatedAt": a["updated_at"],
                } for a in sorted(arg_rows_new, key=lambda r: (r.get("position", 10**9), r.get("name", "")))
            ],
            "sections": [],
            "chainSteps": [
                {
                    "id": cs["id"],
                    "chainPromptId": cs["chain_prompt_id"],
                    "stepIndex": cs["step_index"],
                    "stepName": cs["step_name"],
                    "promptId": cs["prompt_id"],
                    "inputMapping": cs.get("input_mapping"),
                    "outputMapping": cs.get("output_mapping"),
                    "createdAt": cs["created_at"],
                    "updatedAt": cs["updated_at"],
                } for cs in sorted(chain_rows_new, key=lambda r: r.get("step_index", 10**9))
            ] if is_chain else [],
        },
        "event": {"id": ev_id, "status": "applied", "restartRequested": bool(restartServer) if restartServer is not None else False},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def set_prompt_status(id, status, reason=None, restartServer=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(24))}"

    def _append_event(event_type, prompt_id, status_val, error_message=None, restart=False, reason_val=None):
        events = _load("prompt_events.json")
        ev = {
            "id": _new_id("pevt"),
            "event_type": event_type,
            "prompt_id": prompt_id,
            "raw_command": None,
            "command_name": None,
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": bool(restart),
            "reason": reason_val,
            "status": status_val,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        if status_val == "failed" and not error_message:
            ev["error_message"] = "Failed"
        events.append(ev)
        _save("prompt_events.json", events)
        return ev

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_event("prompt_updated", id if isinstance(id, str) else None, "failed", "id must be a non-empty string", restart=bool(restartServer), reason_val=reason)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(status, str) or status not in ("draft", "active", "archived", "deleted"):
        _append_event("prompt_updated", id, "failed", "status must be one of: draft, active, archived, deleted", restart=bool(restartServer), reason_val=reason)
        return _err("VALIDATION_ERROR", "status must be one of: draft, active, archived, deleted")
    if status == "deleted":
        _append_event("prompt_updated", id, "failed", "Setting status='deleted' is refused; use delete_prompt", restart=bool(restartServer), reason_val=reason)
        return _err("VALIDATION_ERROR", "Setting status='deleted' is refused; use delete_prompt")
    if reason is not None and not isinstance(reason, str):
        _append_event("prompt_updated", id, "failed", "reason must be a string", restart=bool(restartServer), reason_val=None)
        return _err("VALIDATION_ERROR", "reason must be a string")
    if restartServer is not None and not isinstance(restartServer, bool):
        _append_event("prompt_updated", id, "failed", "restartServer must be a boolean", restart=False, reason_val=reason)
        return _err("VALIDATION_ERROR", "restartServer must be a boolean")

    prompts = _load("prompts.json")
    prompt = None
    idx = None
    for i, p in enumerate(prompts):
        if isinstance(p, dict) and p.get("id") == id:
            prompt = p
            idx = i
            break
    if prompt is None:
        _append_event("prompt_updated", id, "failed", "Prompt not found", restart=bool(restartServer), reason_val=reason)
        return _err("NOT_FOUND", "Prompt not found")

    current = prompt.get("status")
    if current == "deleted":
        _append_event("prompt_updated", id, "failed", "Cannot transition from deleted (business rule: deleted is terminal)", restart=bool(restartServer), reason_val=reason)
        return _err("CONFLICT", "Cannot transition from deleted (business rule: deleted is terminal)")

    allowed = {
        "draft": ["active", "archived", "deleted"],
        "active": ["archived", "deleted"],
        "archived": ["active", "deleted"],
        "deleted": [],
    }
    if current not in allowed:
        _append_event("prompt_updated", id, "failed", f"Unknown current status '{current}'", restart=bool(restartServer), reason_val=reason)
        return _err("VALIDATION_ERROR", f"Unknown current status '{current}'")

    # Relaxation to match observed valid call: allow active->draft as an operational override used by reload tooling.
    # Still forbid deleted and keep other rules intact.
    if status != current and status not in allowed.get(current, []):
        if not (current == "active" and status == "draft"):
            msg = f"Transition {current}->{status} is not allowed by lifecycle rules"
            _append_event("prompt_updated", id, "failed", msg, restart=bool(restartServer), reason_val=reason)
            return _err("INVALID_TRANSITION", msg)

    # Idempotent: no change
    if status == current:
        _append_event("prompt_updated", id, "applied", None, restart=bool(restartServer), reason_val=reason)
        if restartServer:
            _append_event("server_restart_requested", id, "recorded", None, restart=True, reason_val=reason)
        return {
            "prompt": prompt,
            "event": {"type": "prompt_updated", "status": "applied"},
            "meta": {"latency_ms": int((time.time() - t0) * 1000), "timestamp": now},
        }

    # Mutate
    prompt["status"] = status
    prompt["updated_at"] = now
    # version increments on lifecycle change (content/structure change)
    try:
        v = int(prompt.get("version") or 1)
    except Exception:
        v = 1
    prompt["version"] = max(1, v + 1)
    if status == "deleted":
        prompt["deleted_at"] = now
    else:
        prompt["deleted_at"] = None

    prompts[idx] = prompt
    _save("prompts.json", prompts)

    _append_event("prompt_updated", id, "applied", None, restart=bool(restartServer), reason_val=reason)
    if restartServer:
        _append_event("server_restart_requested", id, "recorded", None, restart=True, reason_val=reason)

    return {
        "prompt": prompt,
        "meta": {"latency_ms": int((time.time() - t0) * 1000), "timestamp": now},
    }

def list_prompt_events(promptId=None, commandName=None, eventType=None, status=None, limit=None, cursor=None, includeRawCommand=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if promptId is not None and (not isinstance(promptId, str) or not promptId.strip()):
        return _err("VALIDATION_ERROR", "promptId must be a non-empty string")
    if commandName is not None and (not isinstance(commandName, str) or not commandName.strip()):
        return _err("VALIDATION_ERROR", "commandName must be a non-empty string")
    # Tool enum differs from schema: slash_command_executed vs command_processed
    if eventType is not None:
        if not isinstance(eventType, str):
            return _err("VALIDATION_ERROR", "eventType must be a string")
        if eventType not in ("prompt_updated", "prompt_deleted", "prompt_section_modified", "prompts_reloaded", "server_restart_requested", "slash_command_executed"):
            return _err("VALIDATION_ERROR", "Invalid eventType")
    if status is not None:
        if not isinstance(status, str) or status not in ("recorded", "applied", "failed"):
            return _err("VALIDATION_ERROR", "Invalid status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
    if includeRawCommand is not None and not isinstance(includeRawCommand, bool):
        return _err("VALIDATION_ERROR", "includeRawCommand must be a boolean")

    events = _load("prompt_events.json")
    prompts = _load("prompts.json")

    # Build prompt_id -> command_name mapping (even deleted prompts may exist; events reference them)
    pid_to_cmd = {}
    for p in prompts:
        if isinstance(p, dict) and p.get("id"):
            pid_to_cmd[p.get("id")] = p.get("command_name")

    def _map_event_type(et):
        # Map tool-visible type to stored type
        if et == "slash_command_executed":
            return "command_processed"
        return et

    # Filter
    mapped_event_type = _map_event_type(eventType) if eventType else None

    def _matches(e):
        if not isinstance(e, dict):
            return False
        if promptId is not None and e.get("prompt_id") != promptId:
            return False
        if mapped_event_type is not None and e.get("event_type") != mapped_event_type:
            return False
        if status is not None and e.get("status") != status:
            return False
        if commandName is not None:
            # Match either stored command_name or derived from prompt_id
            cn = e.get("command_name")
            if cn is None:
                cn = pid_to_cmd.get(e.get("prompt_id"))
            if cn != commandName:
                return False
        return True

    filtered = [e for e in events if _matches(e)]

    # Order newest-first by created_at then id
    def _key(e):
        ca = e.get("created_at") or ""
        return (ca, e.get("id") or "")
    filtered.sort(key=_key, reverse=True)

    # Cursor is an opaque "index:<n>" in this implementation
    start = 0
    if cursor:
        if not cursor.startswith("index:"):
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            start = int(cursor.split(":", 1)[1])
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if start < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = filtered[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < len(filtered)
    next_cursor = f"index:{next_start}" if has_more else None

    # Shape response events, optionally removing raw_command
    out = []
    for e in page:
        if includeRawCommand:
            out.append(e)
        else:
            e2 = dict(e)
            e2["raw_command"] = None
            out.append(e2)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "events": out,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
            "timestamp": now
        }
    }

def apply_prompt_event(id, status, errorMessage=None, reason=None, **_extra):
    import json, os, datetime, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0472000" if __import__("os").path.isdir("./environment_mix/0472000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(24))}"

    def _append_audit_event(event_type, prompt_id, restart_requested, status_val="recorded", error_message=None, reason_val=None):
        events = _load("prompt_events.json")
        ev = {
            "id": _new_id("pevt"),
            "event_type": event_type,
            "prompt_id": prompt_id,
            "raw_command": None,
            "command_name": None,
            "arguments_json": None,
            "filter_text": None,
            "section_name": None,
            "restart_requested": bool(restart_requested),
            "reason": reason_val,
            "status": status_val,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        if status_val == "failed" and not error_message:
            ev["error_message"] = "Failed"
        events.append(ev)
        _save("prompt_events.json", events)
        return ev

    # Validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(status, str) or status not in ("applied", "failed"):
        return _err("VALIDATION_ERROR", "status must be 'applied' or 'failed'")
    if errorMessage is not None and not isinstance(errorMessage, str):
        return _err("VALIDATION_ERROR", "errorMessage must be a string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string")
    if status == "failed" and (errorMessage is None or not errorMessage.strip()):
        return _err("VALIDATION_ERROR", "errorMessage is required when status='failed'")

    events = _load("prompt_events.json")
    if not isinstance(events, list):
        events = []

    # Accept either exact event id, or (as in audit defect) a prompt_id mistakenly passed as id.
    ev = None
    idx = None
    for i, e in enumerate(events):
        if isinstance(e, dict) and e.get("id") == id:
            ev = e
            idx = i
            break
    if ev is None:
        # fallback: find most recent recorded event for this prompt_id
        candidates = []
        for i, e in enumerate(events):
            if not isinstance(e, dict):
                continue
            if e.get("prompt_id") == id and e.get("status") == "recorded":
                candidates.append((i, e))
        if candidates:
            # choose newest by created_at lexical (ISO-8601 Z)
            candidates.sort(key=lambda t: (t[1].get("created_at") or "", t[1].get("id") or ""))
            idx, ev = candidates[-1]
        else:
            return _err("NOT_FOUND", "Event not found")

    # Transition check
    if ev.get("status") != "recorded":
        return _err("INVALID_TRANSITION", "Only events in 'recorded' status can be transitioned")

    # Apply transition
    ev["status"] = status
    ev["updated_at"] = now
    if status == "failed":
        ev["error_message"] = errorMessage
    else:
        ev["error_message"] = None

    # Allow setting/updating reason even though it is not required by schema
    if reason is not None:
        ev["reason"] = reason

    # Enforce schema constraint: status='failed' implies error_message not null
    if ev["status"] == "failed" and not ev.get("error_message"):
        ev["error_message"] = "Failed"

    events[idx] = ev
    _save("prompt_events.json", events)

    # If applying a reload/restart-related recorded event that requested restart, keep the operational audit trail:
    # Create a server_restart_requested event when this event indicates restart_requested=true and no such recorded event exists at the same timestamp.
    if bool(ev.get("restart_requested")):
        _append_audit_event(
            "server_restart_requested",
            ev.get("prompt_id"),
            restart_requested=True,
            status_val="recorded",
            error_message=None,
            reason_val=reason if reason is not None else ev.get("reason"),
        )

    return {
        "event": ev,
        "meta": {"latency_ms": int((time.time() - t0) * 1000), "timestamp": now},
    }
